insert into public.finding_type (key, label, definition) values
('dent', 'Dent', 'Localized inward/outward deformation without defining structural damage.'),
('scratch', 'Scratch', 'Linear surface abrasion or finish damage.'),
('scuff', 'Scuff', 'Broad superficial abrasion or transfer mark.'),
('chip', 'Chip', 'Small localized loss/chip in paint, coating, or glass.'),
('crack', 'Crack', 'Visible fracture or split.'),
('broken', 'Broken', 'Component visibly fractured or no longer physically intact.'),
('bent', 'Bent', 'Component visibly bent from expected geometry.'),
('deformation', 'Deformation', 'Shape differs materially from expected form.'),
('loose', 'Loose', 'Visible movement/gap suggests insecure attachment.'),
('missing', 'Missing', 'Expected component is visibly absent.'),
('misaligned', 'Misaligned', 'Panel/component gaps or geometry visibly inconsistent.'),
('rust', 'Rust', 'Visible iron-oxide rust.'),
('corrosion', 'Corrosion', 'Visible corrosion/oxidation affecting material.'),
('paint_damage', 'Paint damage', 'Paint/coating damage not otherwise classified.'),
('clearcoat_damage', 'Clearcoat damage', 'Visible clear-coat failure, peeling, or checking.'),
('fading', 'Fading', 'Visible color/finish fade compared with surrounding area.'),
('peeling', 'Peeling', 'Coating, film, material, or finish visibly peeling.'),
('delamination', 'Delamination', 'Layers visibly separating.'),
('shattered', 'Shattered', 'Glass is extensively fractured into many pieces/fragments.'),
('cloudy', 'Cloudy', 'Loss of optical clarity/haze.'),
('pitting', 'Pitting', 'Multiple small impact/corrosion pits.'),
('torn', 'Torn', 'Material visibly torn.'),
('punctured', 'Punctured', 'Localized penetration/hole.'),
('frayed', 'Frayed', 'Fibers/strands visibly frayed.'),
('dry_rot', 'Dry rot', 'Cracking/aging pattern consistent with degraded rubber.'),
('bulge', 'Bulge', 'Localized outward bulge/swelling.'),
('leak', 'Leak', 'Visible active fluid escape or clear wet source evidence.'),
('seepage', 'Seepage', 'Light wetness/residue consistent with slow seepage.'),
('excessive_wear', 'Excessive wear', 'Wear appears beyond normal/acceptable visual range.'),
('heat_damage', 'Heat damage', 'Visible heat discoloration, melting, charring, or thermal deformation.'),
('previous_repair', 'Previous repair', 'Visible evidence consistent with prior repair/refinish.'),
('overspray', 'Overspray', 'Paint/coating overspray visible on adjacent surfaces.'),
('water_intrusion', 'Water intrusion', 'Visible water entry, staining, or trapped moisture evidence.'),
('damaged', 'Damaged', 'Visible or documented damage not more specifically classified.'),
('worn', 'Worn', 'Observable wear is present but not necessarily beyond an allowable limit.'),
('uneven_wear', 'Uneven wear', 'Wear is materially non-uniform across the component or contact surface.'),
('abrasion', 'Abrasion', 'Surface material has been worn or rubbed away.'),
('gouge', 'Gouge', 'Deep localized material loss or cut-like surface damage.'),
('cut', 'Cut', 'Material has a visible cut or slice.'),
('disconnected', 'Disconnected', 'A connection that should be joined is visibly or functionally disconnected.'),
('unsecured', 'Unsecured', 'Component is present but not securely retained or fastened.'),
('chafed', 'Chafed', 'Surface wear from repeated rubbing/contact is visible.'),
('exposed_conductor', 'Exposed conductor', 'Electrical conductor is visible due to damaged or missing insulation.'),
('connector_damage', 'Connector damage', 'Electrical connector housing, pins, lock, or seal is visibly damaged.'),
('melted', 'Melted', 'Material is visibly melted or softened by heat.'),
('burn_damage', 'Burn damage', 'Charring, scorching, or other visible burn damage is present.'),
('discolored', 'Discolored', 'Abnormal or localized discoloration is visible.'),
('contaminated', 'Contaminated', 'Foreign material or fluid contamination is visibly present.'),
('debris_buildup', 'Debris buildup', 'Debris accumulation is visibly significant.'),
('obstructed', 'Obstructed', 'Opening, passage, lens, sensor, or moving area is visibly blocked.'),
('collapsed', 'Collapsed', 'Component is visibly collapsed from its expected shape.'),
('swollen', 'Swollen', 'Component is visibly swollen or expanded beyond expected geometry.'),
('glazed', 'Glazed', 'Surface has a smooth/glassy appearance consistent with glazing.'),
('scored', 'Scored', 'Surface has visible scoring lines or grooves from contact/wear.'),
('grooved', 'Grooved', 'Pronounced wear grooves are visible in a contact surface.'),
('residue', 'Residue', 'Residue or staining is visible without enough evidence to call an active leak.'),
('low_level', 'Low level', 'Measured or clearly visible level is below the applicable reference range.'),
('overfilled', 'Overfilled', 'Measured or clearly visible level is above the applicable reference range.'),
('low_tread', 'Low tread', 'Tread depth is visually or measurably low.'),
('abnormal_noise', 'Abnormal noise', 'Component/system produces an abnormal sound during an applicable test.'),
('excessive_play', 'Excessive play', 'Measured or observed free play exceeds expected behavior.'),
('binding', 'Binding', 'Movement is restricted, sticking, or binding during an applicable test.'),
('inoperative', 'Inoperative', 'Component does not operate during an applicable functional test.'),
('intermittent', 'Intermittent', 'Component or function operates inconsistently during testing.'),
('out_of_spec', 'Out of spec', 'Measured value is outside the applicable vehicle/component specification.'),
('unreadable', 'Unreadable', 'Required text, marking, label, display, or identifier cannot be reliably read.'),
('damaged_seal', 'Damaged seal', 'Seal, gasket, weatherstrip, or boot is visibly damaged.'),
('warning_indicator_on', 'Warning indicator on', 'A warning indicator remains illuminated with the engine running.'),
('low_pressure', 'Low pressure', 'Measured pressure is below the applicable specification.'),
('over_pressure', 'Over pressure', 'Measured pressure is above the applicable specification.'),
('aged', 'Aged', 'Component age (date code or install date) exceeds the recommended service life.'),
('exposed_cord', 'Exposed cord', 'Tire cords/belts are visible through tread or sidewall.'),
('dim', 'Dim', 'Lamp operates but output is visibly reduced.'),
('misaimed', 'Misaimed', 'Beam or sensor aim is visibly outside the expected pattern.'),
('streaking', 'Streaking', 'Wiper leaves streaks, smears or chatters.'),
('failed_test', 'Failed test', 'Component failed an instrument or functional test (tester, gauge, strip, pressure test, scan).'),
('service_due', 'Service due', 'Scheduled service interval (miles/time) is reached or exceeded.'),
('discharged', 'Discharged', 'Battery state of charge is low; recharge and retest before condemning.'),
('sagging', 'Sagging', 'Component or ride height sits visibly lower than expected.'),
('degraded_fluid', 'Degraded fluid', 'Fluid is dark, burnt, sludgy, milky or otherwise degraded.'),
('poor_performance', 'Poor performance', 'System operates but below the expected output (e.g. A/C vent temperature, heater output).')
